nextflow_process {

    name "Test Process RIBOCODE_PREPARE"
    script "../main.nf"
    process "RIBOCODE_PREPARE"

    tag "modules"
    tag "modules_nfcore"
    tag "ribocode"
    tag "ribocode/prepare"
    tag "gunzip"

    setup {
        run("GUNZIP", alias: "GUNZIP_FASTA") {
            script "../../../gunzip/main.nf"
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/riboseq_expression/Homo_sapiens.GRCh38.dna.chromosome.20.fa.gz", checkIfExists: true)
                ]
                """
            }
        }
        run("GUNZIP", alias: "GUNZIP_GTF") {
            script "../../../gunzip/main.nf"
            process {
                """
                input[0] = [
                    [ id:'genome' ],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/riboseq_expression/ribocode/genome_updated.gtf.gz", checkIfExists: true)
                ]
                """
            }
        }
    }

    test("test_ribocode_prepare") {

        when {
            process {
                """
                input[0] = GUNZIP_FASTA.out.gunzip
                input[1] = GUNZIP_GTF.out.gunzip
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match("process_outputs") },
                { assert snapshot(process.out.findAll { key, val -> key.startsWith("versions") }).match("versions") }
            )
        }
    }

    test("test_ribocode_prepare - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/riboseq_expression/Homo_sapiens.GRCh38.dna.chromosome.20.fa.gz", checkIfExists: true)
                ]
                input[1] = [
                    [ id:'genome' ],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/riboseq_expression/Homo_sapiens.GRCh38.111_chr20.gtf", checkIfExists: true)
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert process.out.annotation[0][1].toString().endsWith('annotation') }
            )
        }
    }
}
